WITH web_events_by_session AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, COUNT(*) AS web_event_count FROM web_events GROUP BY session_id) SELECT s.id, s.device, s.country, webs.page_values, webs.web_event_count FROM sessions s LEFT JOIN web_events_by_session webs ON s.id = webs.session_id ORDER BY s.id DESC
